#[cfg(feature = "visual-validation")]
/// Seeds the real ACP startup presentation without launching machine-local providers.
pub fn prepare_acp_startup_visual_validation(&mut self) {
    self.conversation_mode = ConversationMode::Ask;
    self.selected_ai_family = SelectedAiFamily::Model;
    self.model_backend = ModelBackendPreference::ManagedLocal;
    self.managed_model_id = "visual-managed-model".to_owned();
    self.message_draft.clear();
    self.acp_question = None;
    let session_id = self.selected_session.clone();
    let _ = self.host.append_message(
        &session_id,
        ConversationRole::User,
        "Summarize the player controller architecture.",
    );
    let _ = self.host.append_message(
        &session_id,
        ConversationRole::Assistant,
        "The controller separates input sampling, fixed-step movement, and presentation so runtime input remains deterministic.",
    );
    let _ = self.host.append_message(
        &session_id,
        ConversationRole::System,
        "Could not open ACP session: the previous agent startup ended before negotiation completed.",
    );
    let _ = self.host.append_message(
        &session_id,
        ConversationRole::User,
        "Check the current project and explain the movement path.",
    );
    self.acp_startup = Some(AcpStartupState {
        agent_id: GOOSE_LOCAL_ACP_DESCRIPTOR_ID.to_owned(),
        target: AcpStartupTarget::Ask {
            gameengine_session_id: session_id,
            prompt: "visual validation pending ACP prompt".to_owned(),
        },
        task: AcpSessionStartupTask::visual_pending(),
    });
    self.status = Some("Starting Managed Local and connecting ACP…".to_owned());
}

